import Foundation
import Dispatch

// Container Orchestration - Multi-tenant Isolation Manager

final class TenantContext {
    let tenantId: String
    let namespace: String
    var resourceQuota: Int
    var activeContainers: [String: ContainerHandle]

    init(tenantId: String, namespace: String, quota: Int) {
        self.tenantId = tenantId
        self.namespace = namespace
        self.resourceQuota = quota
        self.activeContainers = [:]
    }
}

final class ContainerHandle {
    let containerId: String
    let image: String
    var state: ContainerState
    weak var ownerContext: TenantContext?
    private var cleanupCallbacks: [() -> Void] = []

    enum ContainerState {
        case running, stopped, evicting
    }

    init(id: String, image: String, owner: TenantContext) {
        self.containerId = id
        self.image = image
        self.state = .running
        self.ownerContext = owner
    }

    func registerCleanup(_ callback: @escaping () -> Void) {
        cleanupCallbacks.append(callback)
    }

    func executeCleanup() {
        for cb in cleanupCallbacks { cb() }
        cleanupCallbacks.removeAll()
    }
}

final class IsolationBoundary {
    private var tenantRegistry: [String: TenantContext] = [:]
    private let registryQueue = DispatchQueue(label: "registry.queue", attributes: .concurrent)
    private var evictionWorkItems: [String: DispatchWorkItem] = [:]

    func registerTenant(_ ctx: TenantContext) {
        registryQueue.async(flags: .barrier) {
            self.tenantRegistry[ctx.tenantId] = ctx
        }
    }

    func lookupTenant(_ tenantId: String) -> TenantContext? {
        var result: TenantContext?
        registryQueue.sync {
            result = self.tenantRegistry[tenantId]
        }
        return result
    }

    func scheduleEviction(tenantId: String, after delay: TimeInterval) {
        let workItem = DispatchWorkItem { [weak self] in
            self?.performEviction(tenantId: tenantId)
        }
        registryQueue.async(flags: .barrier) {
            self.evictionWorkItems[tenantId] = workItem
        }
        DispatchQueue.global().asyncAfter(deadline: .now() + delay, execute: workItem)
    }

    private func performEviction(tenantId: String) {
        var capturedContainers: [ContainerHandle] = []
        var capturedContext: TenantContext?

        registryQueue.sync {
            guard let ctx = self.tenantRegistry[tenantId] else { return }
            capturedContext = ctx
            capturedContainers = Array(ctx.activeContainers.values)
        }

        // Phase 1: Mark containers for eviction
        for container in capturedContainers {
            container.state = .evicting
        }

        // Phase 2: Execute cleanup callbacks BEFORE removing from registry
        // Ensures TenantContext is still alive via capturedContext strong ref
        for container in capturedContainers {
            container.executeCleanup()
        }

        // Phase 3: Remove tenant from registry only after cleanup is complete
        registryQueue.async(flags: .barrier) {
            self.tenantRegistry.removeValue(forKey: tenantId)
            self.evictionWorkItems.removeValue(forKey: tenantId)
            // capturedContext released here, after all cleanup done
            _ = capturedContext
        }
    }
}

final class OrchestrationEngine {
    private let boundary = IsolationBoundary()
    private let containerQueue = DispatchQueue(label: "container.queue")

    func onboardTenant(tenantId: String, namespace: String, quota: Int) -> TenantContext {
        let ctx = TenantContext(tenantId: tenantId, namespace: namespace, quota: quota)
        boundary.registerTenant(ctx)
        return ctx
    }

    func launchContainer(tenant: TenantContext, image: String) -> ContainerHandle {
        let id = UUID().uuidString
        let handle = ContainerHandle(id: id, image: image, owner: tenant)

        // Register cleanup that safely captures tenant via weak reference
        handle.registerCleanup { [weak tenant] in
            guard let tenant = tenant else { return }
            tenant.resourceQuota += 1
            tenant.activeContainers.removeValue(forKey: id)
        }

        containerQueue.sync {
            tenant.activeContainers[id] = handle
            tenant.resourceQuota -= 1
        }

        return handle
    }

    func evictTenant(tenantId: String) {
        boundary.scheduleEviction(tenantId: tenantId, after: 0.05)
    }
}

// Usage simulation
func simulateMultiTenantWorkload() {
    let engine = OrchestrationEngine()

    let tenant = engine.onboardTenant(tenantId: "tenant-alpha", namespace: "ns-alpha", quota: 10)
    let _ = engine.launchContainer(tenant: tenant, image: "nginx:latest")
    let _ = engine.launchContainer(tenant: tenant, image: "redis:7")

    // Trigger eviction - cleanup runs while context is still strongly held
    engine.evictTenant(tenantId: "tenant-alpha")

    Thread.sleep(forTimeInterval: 0.5)
}

simulateMultiTenantWorkload()
